import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as o}from"./chunks/DIS.DdpTdGGD.js";import{_ as a,o as s,c as n,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const B=JSON.parse('{"title":"Impostazioni Bluetooth","description":"","frontmatter":{"source_hash":"c7d2a497a5","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/bluetooth.md","filePath":"it/use/bluetooth.md"}'),r={name:"it/use/bluetooth.md"};function c(d,i,p,u,m,h){return s(),n("div",null,[...i[0]||(i[0]=[l('<p>Il gran numero di produttori di telefoni Android e le particolarità di sensori e bridge hanno reso l&#39;affidabilità della connessione Bluetooth una delle principali difficoltà di xDrip. Questo menu contiene molte impostazioni avanzate che non possono essere standardizzate per tutti i sistemi.</p><div class="info custom-block"><p class="custom-block-title">Configura le impostazioni Bluetooth come indicato qui sotto</p></div><p>Si consiglia di procedere per tentativi, ma cambia una sola impostazione alla volta per non creare ulteriore confusione.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Impostazioni<br>  Impostazioni Meno Usate<br>   <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_bluetooth_settings_grey600_48dp.png" style="width:5%;"> Impostazioni Bluetooth</p></div><h4 id="turn-bluetooth-on" tabindex="-1">Attiva Bluetooth <a class="header-anchor" href="#turn-bluetooth-on" aria-label="Permalink to &quot;Attiva Bluetooth {#turn-bluetooth-on}&quot;">​</a></h4><p>Questa opzione fa sì che xDrip provi ad attivare il Bluetooth.</p><p>Se xDrip si connette a un dispositivo Bluetooth, Attiva Bluetooth è indispensabile.<br> xDrip potrebbe non riuscire a scavalcare del tutto le impostazioni del telefono: se disattivi il Bluetooth nelle impostazioni di Android o metti il telefono in modalità aereo, potrebbe non riuscire a riattivarlo. Il Bluetooth deve essere attivato nelle impostazioni di Android se vuoi che xDrip lo usi.</p><p><em>Collector: gestione BT globale (bridge classico + OB1 Dex) — Dexcom G5/G6/G7, bridge G4/Libre</em></p><div class="admonition xdripitem"><p class="admonition-title">Attiva Bluetooth<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Attiva automaticamente il bluetooth se è spento quando si prova a connettersi a un dispositivo bluetooth</p></div><h4 id="bluetooth-watchdog" tabindex="-1">Watchdog Bluetooth <a class="header-anchor" href="#bluetooth-watchdog" aria-label="Permalink to &quot;Watchdog Bluetooth {#bluetooth-watchdog}&quot;">​</a></h4><p>In caso di dati mancanti per una perdita di connessione Bluetooth, puoi fare in modo che xDrip spenga e riaccenda il Bluetooth del telefono; il tempo predefinito è di 20 minuti senza dati. Puoi personalizzare questo valore.</p><p>Se vedi il messaggio <strong>xDrip turned off Bluetooth</strong>, probabilmente è scattato il watchdog e xDrip sta cercando di ristabilire la connessione con il sensore.</p><p><em>Collector: logica di recupero globale (collector classici + sequencer) — collector Dexcom e basati su bridge</em></p><div class="admonition xdripitem"><p class="admonition-title">Watchdog Bluetooth<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Resetta Bluetooth (spegni e riaccendi) se non si ricevono dati in 20 minuti</p></div><p>Quando il watchdog è attivato, puoi scegliere dopo quanto tempo senza dati deve scattare: 20 (predefinito), 15, 10 o 5 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Valore timer per il watchdog Bluetooth</p><p> Valore in minuti</p></div><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Tieni presente che l&#39;attivazione del watchdog Bluetooth provoca una disconnessione Bluetooth temporanea di tutti i dispositivi connessi. Potresti voler disattivare questa funzione se usi AAPS e il tuo bridge/microinfusore non recupera automaticamente la connessione Bluetooth.<br> Nota che il collector Dexcom (G5/G6/G7/ONE/ONE+/Stelo) ha un proprio watchdog Bluetooth, sempre attivo e non controllato da questa impostazione (l&#39;impostazione Dex Bluetooth Watchdog è stata rimossa nella versione <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.04.22" target="_blank" rel="noreferrer">2026.04.22</a>).</p></div><h4 id="close-gatt-on-ble-disconnect" tabindex="-1">Chiusura GATT per scollegamento BLE <a class="header-anchor" href="#close-gatt-on-ble-disconnect" aria-label="Permalink to &quot;Chiusura GATT per scollegamento BLE {#close-gatt-on-ble-disconnect}&quot;">​</a></h4><p>Quando questa opzione è attivata, xDrip esegue una disconnessione completa seguita da una riconnessione del dispositivo Bluetooth (chiusura del collegamento, rilevamento e connessione) quando la connessione si perde. Poiché questo potrebbe non essere efficace, si consiglia di lasciarla <strong>disattivata</strong>, così che il dispositivo resti in memoria e xDrip provi solo a riconnettersi a un dispositivo BLE già noto.</p><p><em>Collector: collector bridge classico (<code>DexCollectionService</code>) — bridge G4/Libre, BlueReader/Atom/Tomato</em></p><div class="admonition xdripitem"><p class="admonition-title">Chiusura GATT per scollegamento BLE<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Se il watchdog bluetooth si attiva spesso, provare a deselezionare questa opzione per vedere se aiuta</p></div><h4 id="use-scanning" tabindex="-1">Usa scansione <a class="header-anchor" href="#use-scanning" aria-label="Permalink to &quot;Usa scansione {#use-scanning}&quot;">​</a></h4><p>Usa scansione esegue l&#39;equivalente di Scansione Bluetooth dal menu principale per cercare di recuperare una connessione persa. Con i telefoni più recenti non è sempre efficace. Lasciala inizialmente <strong>disattivata</strong>, a meno che non si dimostri utile.</p><p><em>Collector: collector bridge classico (<code>DexCollectionService</code>) — bridge G4/Libre, BluKon</em></p><div class="admonition xdripitem"><p class="admonition-title">Usa scansione<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Scansiona prima di connettersi a xBridge e Libre Bluetooth</p></div><h4 id="use-ble-manager" tabindex="-1">Use BLE manager <a class="header-anchor" href="#use-ble-manager" aria-label="Permalink to &quot;Use BLE manager {#use-ble-manager}&quot;">​</a></h4><p>Usa un sistema di gestione BLE più moderno. Lascialo <strong>disattivato</strong>, a meno che tu non stia risolvendo un problema di connessione e ti sia stato consigliato di provarlo.</p><p><em>Collector: collector bridge classico (<code>DexCollectionService</code>) — dispositivi basati su bridge</em></p><div class="admonition xdripitem"><p class="admonition-title">Use BLE manager<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Use a more modern BLE manager system</p></div><h4 id="trust-auto-connect" tabindex="-1">Trust Auto-Connect <a class="header-anchor" href="#trust-auto-connect" aria-label="Permalink to &quot;Trust Auto-Connect {#trust-auto-connect}&quot;">​</a></h4><p>Trust Auto-Connect dipende molto dal telefono. È <strong>attivato</strong> per impostazione predefinita. Se hai un Samsung, Xiaomi, OnePlus, Oppo, Huawei o Realme probabilmente dovresti disattivarlo. Se perdi spesso la connessione e non riesci a recuperarla, prova a disattivarlo.</p><p><em>Collector: collector bridge classico + collector OB1 Dex — Dexcom G5/G6/G7, dispositivi bridge</em></p><div class="admonition xdripitem"><p class="admonition-title">Trust Auto-Connect<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Usa e confida nella funzione di connessione automatica bluetooth di Android (sconsigliato per miaomiao)</p></div><h4 id="use-background-scan" tabindex="-1">Usa Scansione In Background <a class="header-anchor" href="#use-background-scan" aria-label="Permalink to &quot;Usa Scansione In Background {#use-background-scan}&quot;">​</a></h4><p>Usa Scansione In Background è una funzione delle versioni più recenti di Android, <strong>attivata</strong> per impostazione predefinita. Se perdi regolarmente la connessione, prova a disattivarla.</p><p><em>Collector: collector con sequencer/scansione in background (Android O+) — soprattutto collector Dexcom/BLE</em></p><div class="admonition xdripitem"><p class="admonition-title">Usa Scansione In Background<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utilizza la funzione di scansione bluetooth in background Android 8+</p></div><h4 id="companion-bluetooth" tabindex="-1">Companion Bluetooth <a class="header-anchor" href="#companion-bluetooth" aria-label="Permalink to &quot;Companion Bluetooth {#companion-bluetooth}&quot;">​</a></h4><p>Companion Bluetooth permette all&#39;app di funzionare insieme all&#39;app master Dex connessa al sensore.</p><p><em>Collector: listener compagno BlueTails — trasmettitori Dexcom in configurazioni companion/sniffer</em></p><div class="admonition xdripitem"><p class="admonition-title">Companion Bluetooth<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Use Bluetooth with companion app data source</p></div><h4 id="bluetooth-wakelocks" tabindex="-1">Bluetooth Wakelocks <a class="header-anchor" href="#bluetooth-wakelocks" aria-label="Permalink to &quot;Bluetooth Wakelocks {#bluetooth-wakelocks}&quot;">​</a></h4><p>I Bluetooth wakelock non sono consigliati e vanno lasciati <strong>disattivati</strong>.</p><p><em>Collector: collector classico + percorsi di callback BLE — soprattutto collector basati su bridge</em></p><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Wakelocks<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Vecchi wakelocks bluetooth (possono necessitare più batteria) che potrebbero essere necessari per la ricezione dei bluetooth</p></div><h4 id="xbridge-polling-mode" tabindex="-1">xBridge+ Modalità di Polling <a class="header-anchor" href="#xbridge-polling-mode" aria-label="Permalink to &quot;xBridge+ Modalità di Polling {#xbridge-polling-mode}&quot;">​</a></h4><p>xBridge+ Modalità di Polling permette a xDrip di inviare richieste al bridge. Anche se non ha alcun effetto con altri dispositivi Bluetooth, puoi attivarla se perdi spesso la connessione, perché terrà comunque il Bluetooth del telefono occupato a tentare di connettersi.</p><p><em>Collector: collector bridge classico (<code>DexCollectionService</code>) — xBridge e hardware simile</em></p><div class="admonition xdripitem"><p class="admonition-title">xBridge+ Modalità di Polling<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Supporto sperimentale per la funzione di polling xBridge+</p></div><h4 id="always-discover-services" tabindex="-1">Usa sempre i servizi BT in modalità discover <a class="header-anchor" href="#always-discover-services" aria-label="Permalink to &quot;Usa sempre i servizi BT in modalità discover {#always-discover-services}&quot;">​</a></h4><p>Attivato per impostazione predefinita. Visibile solo con la Modalità Sviluppatore attivata.</p><p><em>Collector: collector bridge classico (<code>DexCollectionService</code>) — dispositivi BLE basati su bridge</em></p><div class="admonition xdripitem"><p class="admonition-title">Usa sempre i servizi BT in modalità discover<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Verifica servizi Bluetooth ad ogni connessione</p></div><h4 id="use-gatt-refresh" tabindex="-1">Use GATT refresh <a class="header-anchor" href="#use-gatt-refresh" aria-label="Permalink to &quot;Use GATT refresh {#use-gatt-refresh}&quot;">​</a></h4><p>Indica se usare il meccanismo di refresh GATT di basso livello. Attivato per impostazione predefinita. Visibile solo con la Modalità Sviluppatore attivata.</p><p><em>Collector: collector OB1 Dex, collector di tipo JamBase — Dexcom G5/G6/G7, Medtrum</em></p><div class="admonition xdripitem"><p class="admonition-title">Use GATT refresh<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Whether to use the low level gatt refresh mechanism</p></div><h4 id="allow-blucon-unbonding" tabindex="-1">Consenti unbonding Blucon <a class="header-anchor" href="#allow-blucon-unbonding" aria-label="Permalink to &quot;Consenti unbonding Blucon {#allow-blucon-unbonding}&quot;">​</a></h4><p>Consenti unbonding Blucon è utile solo se usi un bridge BluCon, perché gli altri non creano un&#39;associazione (bonding) con il telefono. Se ricevi spesso richieste di associazione con questo bridge, disattivalo.</p><p><em>Collector: percorso bridge BluKon/Libre — configurazioni BluKon e bridge Libre affini</em></p><div class="admonition xdripitem"><p class="admonition-title">Consenti unbonding Blucon<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Adatto solo per telefoni che supportano l&#39;accoppiamento automatico</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',63)])])}const x=a(r,[["render",c]]);export{B as __pageData,x as default};
